for trainerName, trainer in pairs(catalog.trainers) do
	local target = catalog[trainer.kind]
	for _, row in ipairs(trainer.rows) do
		row.trainer = trainerName
		table.insert(target, row)
		catalog.byNameRank[trainer.kind .. "\031" .. row.name .. "\031" .. row.rank] = row
	end
end
